function lenientArray<T extends z.ZodType>(schema: T) {
  return z
    .array(z.unknown())
    .optional()
    .default([])
    .transform((items) =>
      items.flatMap((item) => {
        const parsed = schema.safeParse(item);
        return parsed.success ? [parsed.data as z.infer<T>] : [];
      }),
    );
}

